import React, { useEffect, useState, useCallback } from 'react'
import axios from 'axios'
import { Modal, Button, Form } from 'react-bootstrap'
import { PageTitle } from '../../../../_metronic/layout/core'
import { KTIcon } from '../../../../_metronic/helpers'

interface User {
    id: number
    name: string
    email: string
    roles: string[]
    sidebar_access: string[]
    created_at: string
}

const UsersPage: React.FC = () => {
    const [users, setUsers] = useState<User[]>([])
    const [loading, setLoading] = useState<boolean>(true)
    const [error, setError] = useState<string | null>(null)
    const [totalCount, setTotalCount] = useState<number>(0)
    const [currentPage, setCurrentPage] = useState<number>(1)
    const [itemsPerPage, setItemsPerPage] = useState<number>(10)
    const [searchTerm, setSearchTerm] = useState<string>('')

    const [showModal, setShowModal] = useState<boolean>(false)
    const [showDeleteModal, setShowDeleteModal] = useState<boolean>(false)
    const [selectedUser, setSelectedUser] = useState<User | null>(null)
    const [userToDelete, setUserToDelete] = useState<User | null>(null)
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        roles: ['seller'],
        sidebar_access: ['dashboard', 'orders']
    })
    const [isSaving, setIsSaving] = useState(false)
    const [isDeleting, setIsDeleting] = useState(false)

    const fetchUsers = useCallback(async () => {
        setLoading(true)
        try {
            const params = new URLSearchParams()
            params.append('page', currentPage.toString())
            params.append('limit', itemsPerPage.toString())
            if (searchTerm) params.append('search', searchTerm)

            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get(`${apiUrl}/users?${params.toString()}`)
            if (response.data.success) {
                setUsers(response.data.users)
                setTotalCount(response.data.total_count)
            }
        } catch (err) {
            console.error(err)
            setError('Failed to fetch users')
        } finally {
            setLoading(false)
        }
    }, [currentPage, itemsPerPage, searchTerm])

    useEffect(() => {
        const timer = setTimeout(() => {
            fetchUsers()
        }, 500)
        return () => clearTimeout(timer)
    }, [fetchUsers])

    const handleOpenModal = (user: User | null = null) => {
        if (user) {
            setSelectedUser(user)
            setFormData({
                name: user.name,
                email: user.email,
                password: '',
                roles: user.roles || ['seller'],
                sidebar_access: user.sidebar_access || ['dashboard', 'orders']
            })
        } else {
            setSelectedUser(null)
            setFormData({
                name: '',
                email: '',
                password: '',
                roles: ['seller'],
                sidebar_access: ['dashboard', 'orders']
            })
        }
        setShowModal(true)
    }

    const handleSave = async () => {
        setIsSaving(true)
        try {
            if (selectedUser) {
                // Update
                const payload: any = { ...formData }
                if (!payload.password) delete payload.password
                const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
                await axios.put(`${apiUrl}/users/${selectedUser.id}`, payload)
            } else {
                // Create
                const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
                await axios.post(`${apiUrl}/users`, formData)
            }
            setShowModal(false)
            fetchUsers()
        } catch (err: any) {
            console.error(err)
            alert(err.response?.data?.message || 'Error saving user')
        } finally {
            setIsSaving(false)
        }
    }

    const handleDelete = (user: User) => {
        setUserToDelete(user)
        setShowDeleteModal(true)
    }

    const confirmDelete = async () => {
        if (!userToDelete) return
        setIsDeleting(true)
        try {
            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            await axios.delete(`${apiUrl}/users/${userToDelete.id}`)
            setShowDeleteModal(false)
            setUserToDelete(null)
            fetchUsers()
        } catch (err) {
            console.error(err)
            alert('Error deleting user')
        } finally {
            setIsDeleting(false)
        }
    }

    const toggleRole = (role: string) => {
        setFormData(prev => {
            const currentRoles = [...prev.roles]
            const index = currentRoles.indexOf(role)
            if (index > -1) {
                currentRoles.splice(index, 1)
            } else {
                currentRoles.push(role)
            }
            return { ...prev, roles: currentRoles }
        })
    }

    const toggleSidebarAccess = (module: string) => {
        setFormData(prev => {
            const currentAccess = [...prev.sidebar_access]
            const index = currentAccess.indexOf(module)
            if (index > -1) {
                currentAccess.splice(index, 1)
            } else {
                currentAccess.push(module)
            }
            return { ...prev, sidebar_access: currentAccess }
        })
    }

    const availableRoles = ['admin', 'super admin', 'seller', 'logistic']
    const availableModules = [
        { id: 'dashboard', label: 'Dashboard' },
        { id: 'orders', label: 'All Orders' },
        { id: 'to-confirm', label: 'To Confirm' },
        { id: 'confirmed-orders', label: 'Confirmed' },
        { id: 'tracking', label: 'Tracking' },
        { id: 'products', label: 'Products' },
        { id: 'vendors', label: 'Vendors' },
        { id: 'intigo', label: 'Intigo' },
        { id: 'users', label: 'Users Management' },
        { id: 'history', label: 'History' },
        { id: 'bordereau', label: 'Bordereaux' }
    ]

    return (
        <>
            <PageTitle breadcrumbs={[]}>User Management</PageTitle>
            <div className='card mb-5 mb-xl-8'>
                <div className='card-header border-0 pt-5'>
                    <h3 className='card-title align-items-start flex-column'>
                        <span className='card-label fw-bold fs-3 mb-1'>Users</span>
                        <span className='text-muted mt-1 fw-semibold fs-7'>Total {totalCount} users</span>
                    </h3>
                    <div className='card-toolbar'>
                        <div className='d-flex align-items-center position-relative my-1 me-3'>
                            <KTIcon iconName='magnifier' className='fs-1 position-absolute ms-6' />
                            <input
                                type='text'
                                className='form-control form-control-solid w-250px ps-14'
                                placeholder='Search users'
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <button className='btn btn-primary' onClick={() => handleOpenModal()}>
                            <KTIcon iconName='plus' className='fs-2' /> Add User
                        </button>
                    </div>
                </div>
                <div className='card-body py-3'>
                    <div className='table-responsive'>
                        <table className='table table-row-bordered table-row-gray-100 align-middle gs-0 gy-3'>
                            <thead>
                                <tr className='fw-bold text-muted text-uppercase'>
                                    <th className='min-w-150px'>User</th>
                                    <th className='min-w-140px'>Roles</th>
                                    <th className='min-w-120px'>Created At</th>
                                    <th className='min-w-100px text-end'>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    [...Array(5)].map((_, index) => (
                                        <tr key={`skeleton-${index}`}>
                                            <td>
                                                <div className='d-flex align-items-center'>
                                                    <div className='symbol symbol-45px me-5'>
                                                        <span className='symbol-label placeholder-glow w-45px h-45px'>
                                                            <span className='placeholder w-100 h-100 rounded-circle'></span>
                                                        </span>
                                                    </div>
                                                    <div className='d-flex flex-column flex-grow-1'>
                                                        <span className='placeholder-glow mb-1'><span className='placeholder col-8'></span></span>
                                                        <span className='placeholder-glow'><span className='placeholder col-6'></span></span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td>
                                                <div className="d-flex flex-wrap gap-1">
                                                    <span className='placeholder-glow w-50px'><span className='placeholder col-12 py-3 rounded'></span></span>
                                                    <span className='placeholder-glow w-40px'><span className='placeholder col-12 py-3 rounded'></span></span>
                                                </div>
                                            </td>
                                            <td>
                                                <span className='placeholder-glow'><span className='placeholder col-8'></span></span>
                                            </td>
                                            <td className='text-end'>
                                                <span className='placeholder-glow'><span className='placeholder col-4 py-4 rounded'></span></span>
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    users.map(user => (
                                        <tr key={user.id}>
                                            <td>
                                                <div className='d-flex align-items-center'>
                                                    <div className='symbol symbol-45px me-5'>
                                                        <span className='symbol-label bg-light-danger text-danger fw-bold'>
                                                            {user.name.charAt(0)}
                                                        </span>
                                                    </div>
                                                    <div className='d-flex flex-column'>
                                                        <span className='text-dark fw-bold text-hover-primary fs-6'>{user.name}</span>
                                                        <span className='text-muted fw-semibold fs-7'>{user.email}</span>
                                                    </div>
                                                </div>
                                            </td>
                                            <td>
                                                <div className="d-flex flex-wrap gap-1">
                                                    {user.roles && user.roles.map(role => {
                                                        let badgeColor = 'primary'
                                                        if (role === 'admin' || role === 'super admin') badgeColor = 'danger'
                                                        if (role === 'seller') badgeColor = 'success'
                                                        if (role === 'logistic') badgeColor = 'warning'
                                                        return (
                                                            <span key={role} className={`badge badge-light-${badgeColor} fw-bold text-uppercase`}>{role}</span>
                                                        )
                                                    })}
                                                </div>
                                            </td>
                                            <td>
                                                <span className='text-muted fw-semibold fs-7'>
                                                    {new Date(user.created_at).toLocaleDateString()}
                                                </span>
                                            </td>
                                            <td className='text-end'>
                                                <button className='btn btn-icon btn-bg-light btn-active-color-primary btn-sm me-1' onClick={() => handleOpenModal(user)}>
                                                    <KTIcon iconName='pencil' className='fs-3' />
                                                </button>
                                                <button className='btn btn-icon btn-bg-light btn-active-color-primary btn-sm' onClick={() => handleDelete(user)}>
                                                    <KTIcon iconName='trash' className='fs-3' />
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                    {/* Pagination */}
                    <div className="d-flex justify-content-between align-items-center mt-4">
                        <div className="d-flex align-items-center">
                            <select className="form-select form-select-sm form-select-solid w-70px" value={itemsPerPage} onChange={(e) => setItemsPerPage(Number(e.target.value))}>
                                <option value={10}>10</option>
                                <option value={20}>20</option>
                                <option value={50}>50</option>
                            </select>
                        </div>
                        <div className="d-flex">
                            <button className="btn btn-sm btn-light-primary me-2" onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1}>Prev</button>
                            <span className="align-self-center">Page {currentPage}</span>
                            <button className="btn btn-sm btn-light-primary ms-2" onClick={() => setCurrentPage(p => p + 1)} disabled={users.length < itemsPerPage}>Next</button>
                        </div>
                    </div>
                </div>
            </div>

            <Modal show={showModal} onHide={() => setShowModal(false)} size='lg'>
                <Modal.Header closeButton>
                    <Modal.Title>{selectedUser ? 'Edit User' : 'Add New User'}</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        <div className="row">
                            <div className="col-md-6">
                                <Form.Group className='mb-3'>
                                    <Form.Label className='fw-bold'>Name</Form.Label>
                                    <Form.Control type='text' value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} />
                                </Form.Group>
                                <Form.Group className='mb-3'>
                                    <Form.Label className='fw-bold'>Email</Form.Label>
                                    <Form.Control type='email' value={formData.email} onChange={e => setFormData({ ...formData, email: e.target.value })} />
                                </Form.Group>
                                <Form.Group className='mb-3'>
                                    <Form.Label className='fw-bold'>Password {selectedUser && '(Leave blank to keep current)'}</Form.Label>
                                    <Form.Control type='password' value={formData.password} onChange={e => setFormData({ ...formData, password: e.target.value })} />
                                </Form.Group>
                                <Form.Group className='mb-3'>
                                    <Form.Label className='fw-bold'>Roles</Form.Label>
                                    <div className="d-flex flex-wrap gap-2 mt-2">
                                        {availableRoles.map(role => (
                                            <div key={role} className="form-check form-check-custom form-check-solid">
                                                <input
                                                    className="form-check-input"
                                                    type="checkbox"
                                                    checked={formData.roles.includes(role)}
                                                    onChange={() => toggleRole(role)}
                                                    id={`role-${role}`}
                                                />
                                                <label className="form-check-label text-uppercase fs-7 fw-bold" htmlFor={`role-${role}`}>
                                                    {role}
                                                </label>
                                            </div>
                                        ))}
                                    </div>
                                </Form.Group>
                            </div>
                            <div className="col-md-6 border-start ps-8">
                                <Form.Label className='fw-bold mb-4'>Sidebar Access (Gestions)</Form.Label>
                                <div className="row g-3">
                                    {availableModules.map(module => (
                                        <div key={module.id} className="col-6">
                                            <div className="form-check form-switch form-check-custom form-check-solid">
                                                <input
                                                    className="form-check-input h-20px w-35px"
                                                    type="checkbox"
                                                    checked={formData.sidebar_access.includes(module.id)}
                                                    onChange={() => toggleSidebarAccess(module.id)}
                                                    id={`access-${module.id}`}
                                                />
                                                <label className="form-check-label fs-7" htmlFor={`access-${module.id}`}>
                                                    {module.label}
                                                </label>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className='alert alert-light-primary d-flex align-items-center p-5 mt-5'>
                                    <KTIcon iconName='information-5' className='fs-2hx text-primary me-3' />
                                    <div className='d-flex flex-column'>
                                        <span className='fw-bold fs-7 text-primary'>Permission Control</span>
                                        <span className='fs-8 text-muted'>Select which modules this user should see in the sidebar.</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant='secondary' onClick={() => setShowModal(false)}>Cancel</Button>
                    <Button variant='primary' onClick={handleSave} disabled={isSaving}>
                        {isSaving ? 'Saving...' : 'Save User'}
                    </Button>
                </Modal.Footer>
            </Modal>

            {/* Delete Confirmation Modal */}
            <Modal show={showDeleteModal} onHide={() => setShowDeleteModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Confirm Deletion</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <div className='text-center'>
                        <KTIcon iconName='information-5' className='fs-5tx text-danger mb-5' />
                        <div className='fs-5 fw-bold text-dark'>Are you sure you want to delete user "{userToDelete?.name}"?</div>
                        <div className='text-muted fs-7 mt-2'>This action cannot be undone.</div>
                    </div>
                </Modal.Body>
                <Modal.Footer className='justify-content-center'>
                    <Button variant='light' onClick={() => setShowDeleteModal(false)}>Cancel</Button>
                    <Button variant='danger' onClick={confirmDelete} disabled={isDeleting}>
                        {isDeleting ? 'Deleting...' : 'Delete User'}
                    </Button>
                </Modal.Footer>
            </Modal>
        </>
    )
}

export default UsersPage
